mapper.insert:
INSERT INTO recompute_targets (
	target_type,
	target_id
)
VALUES (
	#{targetType},
	#{targetId}
)
ON DUPLICATE KEY UPDATE
	requested_at = CURRENT_TIMESTAMP

INSERT IGNORE INTO recompute_targets (
	target_type,
	target_id
)
VALUES (
	#{targetType},
	#{targetId}
)

mapper.select:
SELECT
	target_type,
	target_id,
	requested_at
FROM recompute_targets
WHERE target_type = #{targetType}
  AND requested_at <= #{cutoffAt}
ORDER BY requested_at ASC, target_id ASC
LIMIT #{limit}

SELECT COUNT(*)
FROM recompute_targets
WHERE target_type = #{targetType}
  AND requested_at <= #{cutoffAt}

mapper.delete:
DELETE FROM recompute_targets
WHERE target_type = #{targetType}
  AND target_id = #{targetId}
  AND requested_at <= #{cutoffAt}
